SET @prov_c := '%s';
SET	@id := '%s';
SET @cat_id := '%s';
SET	@send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET	@b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_kancha_visit (
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
  total int(9) NOT NULL DEFAULT '0',
  visit int(9) NOT NULL DEFAULT '0',
  result int(9) NOT NULL DEFAULT '0',
  result_visit int(9) NOT NULL DEFAULT '0',
PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_kancha_visit  WHERE id=@id AND b_year=(@b_year+543);
INSERT IGNORE INTO s_kancha_visit  
SELECT 
@id,h.hoscode,CONCAT(h.provcode,h.distcode,h.subdistcode,SUBSTR(CONCAT('00',h.mu),-2)) areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year

,COUNT(DISTINCT CONCAT(s.HOSPCODE,'-',s.PID)) total
,COUNT(DISTINCT CONCAT(s.HOSPCODE,'-',s.PID,'-',s.SEQ)) visit
,COUNT(DISTINCT IF(d.didstd is not null , CONCAT(d.HOSPCODE,'-',d.PID),null)) total_k
,COUNT(DISTINCT IF(d.didstd is not null , CONCAT(d.HOSPCODE,'-',d.PID,'-',d.seq_an),null)) visit_k

FROM tmp_service s  
INNER JOIN chospital h ON s.HOSPCODE=h.hoscode
LEFT JOIN tmp_drug_kancha d  ON s.HOSPCODE = d.HOSPCODE
AND s.pid=d.PID AND s.SEQ=d.SEQ_AN AND d.SOURCE='OPD' AND d.ttm=0
WHERE s.DATE_SERV BETWEEN @start_d AND @end_d
GROUP BY h.hoscode;
